"""The action catalog (`catalog/actions.json`, generated by the Java template) and step matching.

The agents bind scenario steps only to actions listed here. Matching supports the Cucumber
expression subset the library uses: `{string}`, `{int}`, `{float}`, `{word}` and `{}`; anything
else in an expression is matched literally."""

import json
import re
from dataclasses import dataclass
from pathlib import Path

SCHEMA = "stc.action-catalog/1"

_PARAMETERS = {
    "{string}": r"(?:\"[^\"]*\"|'[^']*')",
    "{int}": r"-?\d+",
    "{float}": r"-?\d*\.?\d+",
    "{word}": r"[^\s]+",
    "{}": r".*",
}


class CatalogError(Exception):
    """A catalog that is missing or not the format this tool reads."""


@dataclass(frozen=True)
class Action:
    keyword: str
    expression: str
    description: str
    layer: str


def _regex(expression: str) -> re.Pattern[str]:
    parts = re.split(r"(\{string\}|\{int\}|\{float\}|\{word\}|\{\})", expression)
    body = "".join(_PARAMETERS[p] if p in _PARAMETERS else re.escape(p) for p in parts)
    return re.compile(rf"^{body}$")


def read_catalog(path: Path) -> list[Action]:
    try:
        document = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as error:
        raise CatalogError(f"{path}: {error}") from error
    if not isinstance(document, dict) or document.get("schema") != SCHEMA:
        raise CatalogError(f"{path}: not a {SCHEMA} document")
    return [
        Action(a["keyword"], a["expression"], a["description"], a["layer"])
        for a in document["actions"]
    ]


def matches(actions: list[Action], text: str) -> bool:
    """Whether `text` is an instance of some action of the catalog."""
    return any(_regex(a.expression).match(text) for a in actions)
